import{_ as t,c as o,o as a,ae as r}from"./chunks/framework.CliRSA9F.js";const s="/images/feed_health_check_speed.webp",g=JSON.parse('{"title":"Distribution Health","description":"","frontmatter":{},"headers":[],"relativePath":"features/distribution-health.md","filePath":"features/distribution-health.md"}'),n={name:"features/distribution-health.md"};function i(h,e,l,d,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="distribution-health" tabindex="-1">Distribution Health <a class="header-anchor" href="#distribution-health" aria-label="Permalink to &quot;Distribution Health&quot;">​</a></h1><h2 id="make-sure-every-app-and-directory-can-find-your-show" tabindex="-1">Make Sure Every App and Directory Can Find Your Show <a class="header-anchor" href="#make-sure-every-app-and-directory-can-find-your-show" aria-label="Permalink to &quot;Make Sure Every App and Directory Can Find Your Show&quot;">​</a></h2><p>Distribution Health gives you a complete picture of where your podcast is listed and whether each of those listings is healthy. Your RSS feed is the single file every podcast directory reads, so when it works well your episodes show up everywhere they should — and when something goes wrong, it can quietly affect every app at once. This page helps you confirm your feed is sound, see where your show is distributed, and catch problems before they cost you listeners.</p><p><img src="'+s+'" alt="Distribution Health" width="600px" style="display:block;margin:0 auto;"></p><p><strong>To access</strong>: Navigate to <strong>Traction</strong> in the sidebar, then select the <strong>Distribution</strong> tab.</p><hr><h2 id="your-feed-and-where-you-re-listed" tabindex="-1"><strong>Your Feed and Where You&#39;re Listed</strong> <a class="header-anchor" href="#your-feed-and-where-you-re-listed" aria-label="Permalink to &quot;**Your Feed and Where You&#39;re Listed**&quot;">​</a></h2><p>A row of shortcuts at the top of the page jumps straight to each section: Feed, Website, Primary distribution, Grow your reach, App and directory links, and — when available — Share your show and Reach more listeners.</p><h3 id="distribution-health-warning" tabindex="-1"><strong>Distribution Health Warning</strong> <a class="header-anchor" href="#distribution-health-warning" aria-label="Permalink to &quot;**Distribution Health Warning**&quot;">​</a></h3><p>If something needs attention, a warning banner appears above everything else. It explains the problem in plain terms (for example, a feed issue or a missing platform) and shows an <strong>X% health</strong> badge. The percentage reflects whether your show is listed on the four major apps — Apple Podcasts, Spotify, Amazon Music, and YouTube Music — and whether your RSS feed responds correctly. Any platform that isn&#39;t available for your show is left out of the calculation. When everything is in place, the banner disappears. Use the button in the banner to jump straight to the feed check.</p><h3 id="feed" tabindex="-1"><strong>Feed</strong> <a class="header-anchor" href="#feed" aria-label="Permalink to &quot;**Feed**&quot;">​</a></h3><p>Your <strong>Feed</strong> is the RSS file every directory pulls from. PodSEO shows your primary feed along with any alternate or redirected feeds it detects, each with a status indicator so you can tell at a glance whether things look healthy or need attention. Having a single, clean primary feed matters: alternate or duplicate feeds can split your stats and confuse directories about which version to follow.</p><p>Under the feed, a freshness panel shows when PodSEO last read your feed and what it currently has on file — <strong>Title</strong>, <strong>Author</strong>, <strong>Description</strong>, <strong>Episodes</strong>, and <strong>Latest episode</strong>. If you just changed something at your host and don&#39;t see it reflected in PodSEO yet, compare these values with what you published, then click <strong>Read it again</strong> to ask PodSEO to re-read your feed. The new values appear within a few minutes.</p><h3 id="website" tabindex="-1"><strong>Website</strong> <a class="header-anchor" href="#website" aria-label="Permalink to &quot;**Website**&quot;">​</a></h3><p>Your <strong>Website</strong> is your show&#39;s home on the web, detected from your RSS feed. A dedicated website is one of the biggest discoverability levers you control, because it&#39;s the only place your show gets Google-indexed pages and a custom domain that no platform can lock away. If PodSEO doesn&#39;t find a custom website (or your feed only points at a hosting or directory page), it flags that here so you know there&#39;s an opportunity to claim that ground.</p><h3 id="primary-distribution" tabindex="-1"><strong>Primary Distribution</strong> <a class="header-anchor" href="#primary-distribution" aria-label="Permalink to &quot;**Primary Distribution**&quot;">​</a></h3><p><strong>Primary distribution</strong> covers the four apps where most podcast listening happens: Apple Podcasts, Spotify, Amazon Music, and YouTube Music. Each platform gets a row with a status indicator:</p><ul><li><strong>Green</strong> — PodSEO found one listing for your show</li><li><strong>Amber</strong> — PodSEO found more than one active listing. A warning explains that multiple listings usually mean duplicates, which split your rankings and reviews. Contact that platform&#39;s support to merge them where possible.</li><li><strong>Red</strong> — no listing found yet. Expand the row and use <strong>Add URL manually</strong> to paste the public page for your show on that platform.</li></ul><p>If you paste your own listing and it was previously attached to an old podcast that has since been deleted from PodSEO, it&#39;s now linked to your show straight away.</p><h3 id="grow-your-reach" tabindex="-1"><strong>Grow Your Reach</strong> <a class="header-anchor" href="#grow-your-reach" aria-label="Permalink to &quot;**Grow Your Reach**&quot;">​</a></h3><p><strong>Grow your reach</strong> lists additional directories that use their own show pages. Check each one for your show and save the link you find so it&#39;s handy. Some of these directories import feeds automatically; others accept submissions. PodSEO keeps the links you save but doesn&#39;t independently verify or monitor them.</p><h3 id="app-and-directory-links" tabindex="-1"><strong>App and Directory Links</strong> <a class="header-anchor" href="#app-and-directory-links" aria-label="Permalink to &quot;**App and Directory Links**&quot;">​</a></h3><p><strong>App and directory links</strong> gives you ready-made links to open your show in more podcast apps and directories. These are generated from your show&#39;s details, so check a link before sharing it widely.</p><h3 id="share-your-show" tabindex="-1"><strong>Share Your Show</strong> <a class="header-anchor" href="#share-your-show" aria-label="Permalink to &quot;**Share Your Show**&quot;">​</a></h3><p>When available, <strong>Share your show</strong> lists smart links — a single URL that sends each listener to the podcast app they use. They&#39;re ideal for your social bios, email signature, and show notes, so you don&#39;t have to maintain a list of app buttons yourself.</p><h3 id="reach-more-listeners" tabindex="-1"><strong>Reach More Listeners</strong> <a class="header-anchor" href="#reach-more-listeners" aria-label="Permalink to &quot;**Reach More Listeners**&quot;">​</a></h3><p>When relevant, <strong>Reach more listeners</strong> suggests regional and niche directories that serve specific languages, countries, or audiences. PodSEO doesn&#39;t track these, so open them directly and submit your show if it fits their audience.</p><hr><h2 id="how-you-appear-on-apple-podcasts" tabindex="-1"><strong>How You Appear on Apple Podcasts</strong> <a class="header-anchor" href="#how-you-appear-on-apple-podcasts" aria-label="Permalink to &quot;**How You Appear on Apple Podcasts**&quot;">​</a></h2><p>Your feed decides <strong>whether</strong> Apple can list your show. This section shows <strong>how</strong> Apple can present it, next to your competitors. Beyond the square cover, Apple uses wide and tall artwork for the shows it features: a large banner at the top of the show page on Apple TV and Mac, a full-page image on iPhone and iPad, and banners in its editorial collections. Many podcasters don&#39;t know this artwork exists, so the card shows it with the real images.</p><p>The card sits below <strong>Primary distribution</strong> (the <strong>On Apple Podcasts</strong> shortcut at the top of the page jumps to it).</p><h3 id="first-step-claim-your-show-on-apple-podcasts-connect" tabindex="-1"><strong>First Step: Claim Your Show on Apple Podcasts Connect</strong> <a class="header-anchor" href="#first-step-claim-your-show-on-apple-podcasts-connect" aria-label="Permalink to &quot;**First Step: Claim Your Show on Apple Podcasts Connect**&quot;">​</a></h3><p>If you&#39;ve never claimed your show on <a href="https://podcastsconnect.apple.com" target="_blank" rel="noreferrer">Apple Podcasts Connect</a>, start there. It&#39;s where you prove the show is yours, manage your Apple listing and see your Apple analytics. The window links to it (<strong>Haven&#39;t claimed your show? Start with Apple Podcasts Connect</strong>); the link is hidden once your Apple Podcasts Connect account is connected to PodSEO in <a href="/features/analytics-connections.html">Analytics Connections</a>. For tips on requesting a feature, see Apple&#39;s guide to <a href="https://podcasters.apple.com/support/1993-optimize-your-request-for-promotion" target="_blank" rel="noreferrer">optimizing your request for promotion</a>.</p><h3 id="what-does-the-your-show-on-apple-podcasts-card-show" tabindex="-1"><strong>What Does the &quot;Your Show on Apple Podcasts&quot; Card Show?</strong> <a class="header-anchor" href="#what-does-the-your-show-on-apple-podcasts-card-show" aria-label="Permalink to &quot;**What Does the &quot;Your Show on Apple Podcasts&quot; Card Show?**&quot;">​</a></h3><p>The card puts your square cover next to a wide preview of the Apple TV and Mac artwork. If Apple has that artwork for your show, you see yours. If not, PodSEO shows one of your competitors&#39; as an example (labelled with its name), or an outline of the format when none of them has it. Below, a short summary says how many editorial images Apple returned for your show and how many of your checked competitors have editorial artwork, plus the date of the last check.</p><p>Click <strong>Explore artwork and compare</strong> to open the full view.</p><h3 id="the-explore-artwork-and-compare-window" tabindex="-1"><strong>The &quot;Explore Artwork and Compare&quot; Window</strong> <a class="header-anchor" href="#the-explore-artwork-and-compare-window" aria-label="Permalink to &quot;**The &quot;Explore Artwork and Compare&quot; Window**&quot;">​</a></h3><p>The window, titled <strong>How Apple can show your podcast</strong>, is a gallery of previews built from the artwork Apple returns for a listing. Each frame is one place where Apple can use artwork:</p><ul><li><strong>Apple TV and Mac</strong> — the wide 16:9 artwork Apple can place at the top of the show page on Apple TV and Mac</li><li><strong>Content logo</strong> — the white logo Apple can lay over the wide artwork</li><li><strong>Show page</strong> — the tall artwork Apple can show behind the show page on iPhone and iPad (Apple&#39;s size: 2048 × 2732 px)</li><li><strong>Editorial banner</strong> — the 4:1 banner Apple&#39;s editors can use when they feature the show</li><li><strong>Subscription banner</strong> — the 4:1 banner Apple can use to promote a show&#39;s subscription</li><li><strong>More artwork variants</strong> — a wide 4:3 backdrop, a 2:3 portrait cover and a tall 3:4 backdrop, behind a disclosure</li></ul><p>Under the gallery, <strong>Listing basics</strong> shows your cover as Apple has it, with the size Apple reports, and the categories Apple shows for the show.</p><p>These are previews of possible placements, not screenshots of what Apple is showing today. Having this artwork doesn&#39;t mean Apple is promoting the show right now, and submitting it doesn&#39;t guarantee a placement: <strong>Apple decides what it features</strong>.</p><h3 id="what-does-not-returned-by-apple-mean" tabindex="-1"><strong>What Does &quot;Not Returned by Apple&quot; Mean?</strong> <a class="header-anchor" href="#what-does-not-returned-by-apple-mean" aria-label="Permalink to &quot;**What Does &quot;Not Returned by Apple&quot; Mean?**&quot;">​</a></h3><p>When Apple has no artwork for a placement, the frame stays empty, shows the size Apple asks for, and reads <strong>Not returned by Apple</strong>. It means Apple didn&#39;t return that artwork for the listing. It isn&#39;t an error and it doesn&#39;t affect your health score or any other PodSEO score. Most shows have only the square cover: Apple usually has editorial artwork for shows it has chosen to feature.</p><p>If a preview reads <strong>Preview unavailable</strong>, the image couldn&#39;t be loaded this time; it doesn&#39;t mean the artwork is missing.</p><h3 id="how-do-i-compare-my-apple-listing-with-competitors" tabindex="-1"><strong>How Do I Compare My Apple Listing With Competitors?</strong> <a class="header-anchor" href="#how-do-i-compare-my-apple-listing-with-competitors" aria-label="Permalink to &quot;**How Do I Compare My Apple Listing With Competitors?**&quot;">​</a></h3><p>Use the <strong>Showing</strong> menu at the top of the window to switch between <strong>Your show</strong> and each of your competitors. The gallery keeps the same order, so you can compare placement by placement. Under each main frame (not the ones under <strong>More artwork variants</strong>), <strong>Also has this</strong> shows small thumbnails of the other shows that have that artwork; click one to switch the gallery to that show. When none of them has it, the frame reads <strong>No other checked listing has this</strong>.</p><p>If you haven&#39;t added competitors yet, use <strong>Add competitors to compare</strong>. If none of the checked shows has editorial artwork, the window says so: that&#39;s common in many niches and not something you did wrong.</p><h3 id="how-do-i-fix-my-cover-or-categories-on-apple-podcasts" tabindex="-1"><strong>How Do I Fix My Cover or Categories on Apple Podcasts?</strong> <a class="header-anchor" href="#how-do-i-fix-my-cover-or-categories-on-apple-podcasts" aria-label="Permalink to &quot;**How Do I Fix My Cover or Categories on Apple Podcasts?**&quot;">​</a></h3><p>Your cover and categories come from your RSS feed, so change them in your podcast hosting platform:</p><ul><li><strong>Cover art</strong> — Apple asks for a square image between 1,400 and 3,000 px. If yours is smaller, the window flags it with <strong>Below the 1,400 px Apple asks for</strong>.</li><li><strong>Categories</strong> — choose the categories that describe your show in your host&#39;s settings. If Apple only shows the generic &quot;Podcasts&quot;, your show has no specific category on Apple.</li></ul><p>Apple picks up the change the next time it reads your feed; PodSEO shows it after its next check.</p><h3 id="how-do-i-get-the-new-apple-tv-and-mac-artwork" tabindex="-1"><strong>How Do I Get the New Apple TV and Mac Artwork?</strong> <a class="header-anchor" href="#how-do-i-get-the-new-apple-tv-and-mac-artwork" aria-label="Permalink to &quot;**How Do I Get the New Apple TV and Mac Artwork?**&quot;">​</a></h3><p>The wide Apple TV and Mac artwork and the content logo are by invitation: Apple emails the shows it invites and asks for two files.</p><ul><li><strong>Universal Art</strong> — 16:9, 5244 × 2950 px, as a PSD and a PNG, with no text or logos in the image</li><li><strong>Content Logo</strong> — white, 4320 × 1300 px, on a transparent background</li><li>Both in the <strong>Display P3</strong> color space, <strong>16-bit</strong></li></ul><p>Upload them through the <strong>Box link in Apple&#39;s email</strong>. If you haven&#39;t received that email, Apple hasn&#39;t invited your show yet. Inside the window, <strong>How to provide artwork</strong> summarizes the same steps.</p><h3 id="how-often-is-my-apple-listing-checked" tabindex="-1"><strong>How Often Is My Apple Listing Checked?</strong> <a class="header-anchor" href="#how-often-is-my-apple-listing-checked" aria-label="Permalink to &quot;**How Often Is My Apple Listing Checked?**&quot;">​</a></h3><p>PodSEO checks your show and your competitors on Apple Podcasts once a week, and right after you add a show or a competitor. The card and the window show the date of the last check. A show reads <strong>Not checked yet</strong> until its first check, and <strong>No Apple Podcasts listing linked</strong> when PodSEO doesn&#39;t know its Apple listing: add it in <strong>Primary distribution</strong> with <strong>Add URL manually</strong>.</p><hr><h2 id="feed-analysis" tabindex="-1"><strong>Feed Analysis</strong> <a class="header-anchor" href="#feed-analysis" aria-label="Permalink to &quot;**Feed Analysis**&quot;">​</a></h2><p>Expand <strong>Check feed health</strong> and click <strong>Run feed check</strong> to run a full read of your RSS feed. Run it again whenever you want to re-test your feed. The analysis validates how your feed is built and surfaces anything that could trip up the apps that rely on it.</p><h3 id="feed-status-and-health-checklist" tabindex="-1"><strong>Feed Status and Health Checklist</strong> <a class="header-anchor" href="#feed-status-and-health-checklist" aria-label="Permalink to &quot;**Feed Status and Health Checklist**&quot;">​</a></h3><p>The analysis leads with a clear <strong>Well-Formed</strong> or <strong>Malformed</strong> status, then a short pass/fail checklist covering the essentials:</p><ul><li><strong>Well-formed XML</strong> — Confirms your feed is structured correctly so directories can read it</li><li><strong>Valid Episodes</strong> — How many of your episodes are valid out of the total found in the feed</li><li><strong>Podcast 2.0 Tags</strong> — Whether your feed uses the newer Podcast 2.0 tags that unlock richer features in modern apps</li><li><strong>Feed Size</strong> — The overall size of your feed file</li></ul><p>You&#39;ll also see a quick <strong>Feed Statistics</strong> summary of your total and valid episode counts, and — when present — the specific Podcast 2.0 features your feed includes.</p><h3 id="issues-found" tabindex="-1"><strong>Issues Found</strong> <a class="header-anchor" href="#issues-found" aria-label="Permalink to &quot;**Issues Found**&quot;">​</a></h3><p>Rather than reducing everything to a single number, Distribution Health tells you exactly what needs attention by listing the specific <strong>Issues Found</strong> in your feed, grouped into:</p><ul><li><strong>Errors</strong> — Problems that can prevent your feed from being read or distributed correctly, which should be fixed first</li><li><strong>Warnings</strong> — Less urgent issues worth reviewing and cleaning up over time</li></ul><p>Each entry describes the issue directly so you know what to take to your podcast host. If your feed is clean, you simply won&#39;t see any errors or warnings — that&#39;s a good sign.</p><hr><h2 id="feed-fetch-performance" tabindex="-1"><strong>Feed Fetch Performance</strong> <a class="header-anchor" href="#feed-fetch-performance" aria-label="Permalink to &quot;**Feed Fetch Performance**&quot;">​</a></h2><p>A core part of this page is the <strong>Feed Fetch Performance</strong> panel, which measures how quickly your feed actually loads — and what it has to go through to get there.</p><p>Every analytics tracker or ad-insertion service you add to your feed creates a redirect — an extra hop between a directory requesting your feed and actually receiving it. Stacking multiple redirects slows things down, inflates your feed size, and can cause failures on some platforms.</p><p>This panel shows:</p><ul><li><strong>Initial and final URL</strong> — Where the request starts and where it ends up after any redirects</li><li><strong>Redirect chain</strong> — Each hop in the chain, with its response status and the time that hop took, so you can see exactly where delay is being introduced</li><li><strong>Total time</strong> — How long the whole fetch took from start to finish</li><li><strong>Feed size</strong> — Your feed file size, graded so you can tell at a glance whether it&#39;s a good size, getting large, or too large</li><li><strong>Redirects</strong> — The total number of hops in the chain</li></ul><p>If you see a long redirect chain or slow total time, review which tracking services are still necessary and remove any you no longer use. For a deeper look at why this matters, see our academy article on <a href="/academy/why-multiple-podcast-trackers-are-a-recipe-for-disaster.html">why multiple podcast trackers are a recipe for disaster</a>.</p><hr><h2 id="how-to-use-distribution-health" tabindex="-1"><strong>How to Use Distribution Health</strong> <a class="header-anchor" href="#how-to-use-distribution-health" aria-label="Permalink to &quot;**How to Use Distribution Health**&quot;">​</a></h2><ol><li><strong>Start with the feed status.</strong> Confirm your feed reads as Well-Formed and that your valid episode count matches what you expect. A Malformed feed is the most important thing to fix.</li><li><strong>Work through any errors, then warnings.</strong> Errors can block distribution, so address those first; warnings are cleanup you can schedule.</li><li><strong>Check your fetch performance.</strong> If your total fetch time is high or your redirect chain is long, trim trackers you no longer need and consider whether your feed size is creeping into &quot;large&quot; territory.</li><li><strong>Confirm your platform listings and website.</strong> Make sure each Primary distribution row is green, add any missing listing with <strong>Add URL manually</strong>, merge duplicate listings, and claim a custom website if you don&#39;t have one yet.</li><li><strong>See how you appear on Apple Podcasts.</strong> Click <strong>Explore artwork and compare</strong>, check your cover size and categories, and compare the artwork Apple has for your competitors.</li><li><strong>Take fixes to your host.</strong> Many feed-level changes are made through your podcast hosting platform, so use the specific issues listed here as your checklist when you update your settings.</li></ol><hr><h2 id="best-practices-for-distribution-health" tabindex="-1"><strong>Best Practices for Distribution Health</strong> <a class="header-anchor" href="#best-practices-for-distribution-health" aria-label="Permalink to &quot;**Best Practices for Distribution Health**&quot;">​</a></h2><h3 id="check-after-changes" tabindex="-1"><strong>Check After Changes</strong> <a class="header-anchor" href="#check-after-changes" aria-label="Permalink to &quot;**Check After Changes**&quot;">​</a></h3><p>Revisit Distribution Health after you change your hosting setup, update metadata, or add or remove a tracker. This is the fastest way to confirm a change had the effect you intended and didn&#39;t introduce a new issue.</p><h3 id="keep-your-redirect-chain-short" tabindex="-1"><strong>Keep Your Redirect Chain Short</strong> <a class="header-anchor" href="#keep-your-redirect-chain-short" aria-label="Permalink to &quot;**Keep Your Redirect Chain Short**&quot;">​</a></h3><p>Each tracker you stack onto your feed adds time and size. Periodically prune services you no longer use — a shorter chain means faster loads and fewer chances for playback failures.</p><h3 id="consolidate-to-a-single-clean-feed" tabindex="-1"><strong>Consolidate to a Single Clean Feed</strong> <a class="header-anchor" href="#consolidate-to-a-single-clean-feed" aria-label="Permalink to &quot;**Consolidate to a Single Clean Feed**&quot;">​</a></h3><p>Multiple active or duplicate feeds can split your stats and send directories to the wrong place. Aim for one clear primary feed that every app follows.</p><h3 id="claim-your-own-website" tabindex="-1"><strong>Claim Your Own Website</strong> <a class="header-anchor" href="#claim-your-own-website" aria-label="Permalink to &quot;**Claim Your Own Website**&quot;">​</a></h3><p>If Distribution Health flags a missing custom website, it&#39;s worth acting on. A dedicated site gives your show indexed pages and a presence that doesn&#39;t depend on any single platform.</p><hr><h2 id="working-with-other-podseo-features" tabindex="-1"><strong>Working with Other PodSEO Features</strong> <a class="header-anchor" href="#working-with-other-podseo-features" aria-label="Permalink to &quot;**Working with Other PodSEO Features**&quot;">​</a></h2><p>A healthy, fast-loading feed supports everything else you do in PodSEO. Clean metadata strengthens the keyword work you do in <a href="/features/keyword-strategy.html">Keyword Strategy</a>, and reliable distribution underpins the discoverability you track in <a href="/features/visibility-progress.html">Visibility Progress</a>. You can also see a quick distribution summary on the <a href="/features/podcast-details.html">Overview</a> tab, with a link straight back into this tab when you want the full diagnostic.</p><hr><p><strong>Getting Started</strong>: Open the <strong>Distribution</strong> tab, expand <strong>Check feed health</strong>, click <strong>Run feed check</strong>, and review your feed status, any issues found, and your fetch performance. Use the specific issues listed there as a checklist when you make changes through your podcast host.</p>',93)])])}const w=t(n,[["render",i]]);export{g as __pageData,w as default};
